cy.irAMisPortfolios();
        cy.abrirPortfolio('Portfolio CYPRESS');
        cy.filtrarFechaPosicionValuada("13/03/2026");
        cy.abrirMonedas();
        cy.obtenerSaldoMoneda('ARS').then((saldoAntes) => {
          cy.irAMisOperaciones();
          cy.filtrarFecha("04/02/2026");
          cy.clickearBotonEditar('Suscripción', 'Fondo', _support_constants__WEBPACK_IMPORTED_MODULE_0__["default"].FONDO);
          cy.modificarOperación('2600', 'ARS', '2000');
          cy.asignarPortfolio('1000');
          // Tras editar, el backend puede tardar unos segundos en recalcular la valuación del
          // portfolio: una relectura inmediata del saldo (re-navegando una sola vez, como hacía
          // este test antes) a veces llega ANTES de que ese recálculo termine y lee el valor
          // viejo -- confirmado en vivo: misma sesión sin re-navegar no lo actualiza ni esperando
          // unos segundos, pero SÍ lo actualiza una segunda re-navegación un poco más tarde. Este
          // reintento acotado (re-navegar + releer, no un cy.wait a ciegas) le da a ese recálculo
          // el margen que necesita antes de la aserción final.
          const releerSaldoFondo = (intentosRestantes) => {
            cy.irAMisPortfolios();
            cy.abrirPortfolio('Portfolio CYPRESS');
            cy.filtrarFechaPosicionValuada("13/03/2026");
            cy.abrirMonedas();
            return cy.obtenerSaldoMoneda('ARS').then((saldoActual) => {
              if (saldoActual === saldoAntes && intentosRestantes > 0) {
                // eslint-disable-next-line cypress/no-unnecessary-waiting -- intervalo real de polling del retry acotado (backend recalculando), no una espera de estabilización
                cy.wait(2000);
                return releerSaldoFondo(intentosRestantes - 1);
              }
              return saldoActual;
            });
          };
          // Nuevo precio de suscripción (2600 vs 2700) y un cargo de comisión adicional (2000) --
          // a diferencia de Bonos/Acciones, acá el efecto neto resultó ser una disminución
          // (verificado contra LH: 9.410.700 -> 9.408.800), no el aumento que se esperaba por el
          // precio más bajo -- agregarComision() probablemente suma un cargo nuevo en vez de
          // reemplazar el original, y el pricing de Fondos no escala linealmente con
          // cantidad×precio como Bonos/Acciones. Sin certeza del efecto neto exacto, se usa
          // 'cambio' en vez de asumir una dirección.
          releerSaldoFondo(4).then(() => {
            cy.validarImpactoSaldoMoneda('ARS', saldoAntes, 'cambio');
          });
          cy.abrirYValidarInstrumento('Fondos', _support_constants__WEBPACK_IMPORTED_MODULE_0__["default"].FONDO, '500');
        });

